func attachDistanceOverrideStop(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*distanceoverride.DistanceOverrideStop)(p)
	switch rel {
	case 0:
		r.Location = (*location.Location)(child)
	}
}

func init() {
	distanceOverridesTable.Relations[0].Target = locationdb.LocationsSchema()
	distanceOverridesTable.Relations[1].Target = locationdb.LocationsSchema()
	distanceOverridesTable.Relations[2].Target = customerdb.CustomersSchema()
	distanceOverridesTable.Relations[3].Target = DistanceOverrideStopsSchema()
	distanceOverrideStopsTable.Relations[0].Target = locationdb.LocationsSchema()
}

